package io.github.turbopro.ism.platform.support;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import io.github.turbopro.ism.common.api.error.*;
import io.github.turbopro.ism.common.api.support.SupportRoleAuthority;
import io.github.turbopro.ism.common.infrastructure.authorization.AuthorizationContext;
import io.github.turbopro.ism.common.infrastructure.tenant.TenantContext;
import io.github.turbopro.ism.operation.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.*;
@Service
public class TenantSupportService {
 private static final Set<String> FIELDS=Set.of("id","code","name","type","status");
 private final TenantSupportMapper mapper;private final SupportRequestMapper requests;private final SupportRequestService visibility;private final SupportRoleAuthority roles;private final ObjectMapper json;private final OperationIdGenerator ids;private final AuditService audit;
 public TenantSupportService(TenantSupportMapper mapper,SupportRequestMapper requests,SupportRequestService visibility,SupportRoleAuthority roles,ObjectMapper json,OperationIdGenerator ids,AuditService audit){this.mapper=mapper;this.requests=requests;this.visibility=visibility;this.roles=roles;this.json=json;this.ids=ids;this.audit=audit;}
 @Transactional public TenantSupportModels.Policy policy(){long t=tenant("iam:support:view");knownTenant(t);return policyView(mapper.policy(t),t);}
 @Transactional public List<SupportRoleAuthority.Role> options(){long t=tenant("iam:support:manage");knownTenant(t);return roles.options(t);}
 @Transactional public TenantSupportModels.Policy save(TenantSupportModels.SavePolicy c){long t=tenant("iam:support:manage");knownTenant(t);var old=mapper.policy(t);int version=old==null?0:old.version();if(c.version()!=version)throw conflict();Long role=c.roleId()==null?null:positive(c.roleId());if(c.enabled()&&(role==null||roles.resolve(t,role)==null))throw blocked("角色无供应商只读权限或范围不支持，不能启用");if(c.fields()==null||c.fields().isEmpty()||!FIELDS.containsAll(c.fields()))throw blocked("字段超出基础只读上界");var now=requests.now();if(old==null)mapper.insertPolicy(t,c.enabled(),role,write(new TreeSet<>(c.fields())),c.maxMinutes(),actor(),now);else if(mapper.updatePolicy(t,c.enabled(),role,write(new TreeSet<>(c.fields())),c.maxMinutes(),actor(),now,version)!=1)throw conflict();audit("TENANT_SUPPORT_POLICY",t,Map.of("policyVersion",version+1,"enabled",c.enabled(),"roleId",role==null?"":role.toString(),"fields",new TreeSet<>(c.fields()),"maxMinutes",c.maxMinutes()));return policyView(mapper.policy(t),t);}
 @Transactional public TenantSupportModels.Page list(int page,int size){long t=tenant("iam:support:view");if(page<0||page>10000||size<1||size>100)throw new ApiException(CommonErrorCode.VALIDATION_FAILED);knownTenant(t);var p=mapper.policy(t);var now=requests.now();return new TenantSupportModels.Page(mapper.count(t),page,size,mapper.requests(t,page*size,size).stream().map(r->view(r,p,now,t)).toList());}
 @Transactional public TenantSupportModels.Request get(long id){long t=tenant("iam:support:view");knownTenant(t);var p=mapper.policy(t);return view(owned(id,t,p),p,requests.now(),t);}
 @Transactional public TenantSupportModels.Request decide(long id,String action,TenantSupportModels.Decision c,String name){long t=tenant("iam:support:review");require("iam:support:view");var target=knownTenant(t);var p=mapper.policy(t);var r=owned(id,t,p);r=requests.lock(id);if(c.requestVersion()!=r.version())throw conflict();var now=requests.now();
  if("revoke".equals(action)){var d=mapper.consent(t,id,c.policyVersion());if(d==null||!"APPROVED".equals(d.status())||d.version()!=c.decisionVersion())throw conflict();if(mapper.revoke(t,d.id(),d.version(),actor(),c.comment().trim(),now)!=1)throw conflict();audit("TENANT_SUPPORT_REVOKE",id,Map.of("policyVersion",d.policyVersion(),"decisionId",Long.toString(d.id())));return view(requests.get(id),p,now,t);}
  if(c.policyVersion()!=(p==null?0:p.version())||mapper.consent(t,id,c.policyVersion())!=null||c.decisionVersion()!=0)throw conflict();if(!"PLATFORM_APPROVED".equals(r.status()))throw blocked("尚未平台批准或申请已取消");
  boolean approve="approve".equals(action);if(!approve&&!"reject".equals(action))throw new ApiException(CommonErrorCode.VALIDATION_FAILED);TenantSupportModels.Scope scope=null;LocalDateTime expires=null;Long role=null;
  if(approve){if(target==null||!"ACTIVE".equals(target.status())||!"READY".equals(target.initializationStatus())||!r.requestedExpireAt().isAfter(now)||p==null||!p.enabled()||mapper.eligibleOperator(r.platformOperatorId(),now)==null)throw blocked("租户、申请、策略或平台申请人当前不可授权");scope=proposed(r,p,t);if(scope==null)throw blocked("角色或请求只读范围当前不可用");if(!Objects.equals(c.scopeHash(),scopeHash(r,p,t,scope)))throw conflict();LocalDateTime bound=now.plusMinutes(p.maxMinutes());if(bound.isAfter(r.requestedExpireAt()))bound=r.requestedExpireAt();if(c.expiresAt()==null||!c.expiresAt().isAfter(now)||c.expiresAt().isAfter(bound))throw blocked("授权截止已过或超出请求/策略上界，请重新读取");expires=c.expiresAt();role=p.roleId();}
  mapper.decide(ids.nextId(),id,t,c.policyVersion(),r.version(),approve?"APPROVED":"REJECTED",role,scope==null?null:write(scope),expires,actor(),name,c.comment().trim(),now);audit(approve?"TENANT_SUPPORT_APPROVE":"TENANT_SUPPORT_REJECT",id,Map.of("policyVersion",c.policyVersion(),"actorRealm","TENANT"));return view(requests.get(id),p,now,t);
 }
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
 public TenantSupportModels.Authorization authorization(long id){visibility.get(id);var r=requests.get(id);long t=r.targetTenantId();var tenant=knownTenant(t);var p=mapper.policy(t);r=requests.lock(id);var now=requests.now();var empty=new TenantSupportModels.Scope(false,Set.of(),Set.of());String reason=null;
  if(tenant==null||!"ACTIVE".equals(tenant.status())||!"READY".equals(tenant.initializationStatus()))reason="TENANT_UNAVAILABLE";
  else if(!"PLATFORM_APPROVED".equals(r.status()))reason="PLATFORM_REVIEW_REQUIRED";
  else if(!r.requestedExpireAt().isAfter(now))reason="EXPIRED";
  else if(mapper.eligibleOperator(r.platformOperatorId(),now)==null)reason="OPERATOR_UNAVAILABLE";
  else if(p==null||!p.enabled())reason="POLICY_DISABLED";
  if(reason!=null)return new TenantSupportModels.Authorization(Long.toString(id),false,false,reason,empty,null);
  var d=mapper.consent(t,id,p.version());if(d==null)return new TenantSupportModels.Authorization(Long.toString(id),false,false,"TENANT_REVIEW_REQUIRED",empty,null);
  if(!"APPROVED".equals(d.status())||d.requestVersion()!=r.version())return new TenantSupportModels.Authorization(Long.toString(id),false,false,d.status(),empty,null);
  if(!d.expiresAt().isAfter(now))return new TenantSupportModels.Authorization(Long.toString(id),false,false,"EXPIRED",empty,null);
  var live=proposed(r,p,t);if(live==null)return new TenantSupportModels.Authorization(Long.toString(id),false,false,"ROLE_UNAVAILABLE",empty,null);
  var approved=readScope(d.scopeJson());var fields=new TreeSet<>(approved.fields());fields.retainAll(live.fields());boolean all=approved.tenantAll()&&live.tenantAll();Set<String> orgs=new TreeSet<>(approved.tenantAll()?live.organizations():approved.organizations());if(!approved.tenantAll()&&!live.tenantAll())orgs.retainAll(live.organizations());var scope=new TenantSupportModels.Scope(all,Set.copyOf(orgs),Set.copyOf(fields));boolean ready=!fields.isEmpty()&&(all||!orgs.isEmpty());return new TenantSupportModels.Authorization(Long.toString(id),ready,false,ready?"AUTHORIZATION_READY_SESSION_DISABLED":"EMPTY_INTERSECTION",ready?scope:empty,ready?d.expiresAt():null);
 }
 private TenantSupportModels.Scope proposed(SupportRequestModels.Row r,TenantSupportModels.PolicyRow p,long t){if(p==null||p.roleId()==null)return null;var role=roles.resolve(t,p.roleId());if(role==null)return null;try{var profile=json.readValue(r.profileJson(),SupportRequestModels.Profile.class);if(!"SUPPLIER_BASIC_READ_V1".equals(profile.code())||!Set.copyOf(profile.actions()).equals(Set.of("supplier:master:view"))||!"TENANT_ALL".equals(profile.dataScope())||!FIELDS.containsAll(profile.fields()))return null;var f=new TreeSet<>(readFields(p.allowedFieldsJson()));f.retainAll(profile.fields());return f.isEmpty()?null:new TenantSupportModels.Scope(role.tenantAll(),role.organizations(),Set.copyOf(f));}catch(Exception e){throw new IllegalStateException(e);}}
 private SupportRequestModels.Row owned(long id,long t,TenantSupportModels.PolicyRow p){var r=requests.get(id);if(r==null||r.targetTenantId()!=t||r.submittedAt()==null||!"PLATFORM_APPROVED".equals(r.status())&&mapper.history(t,id).isEmpty())throw new ApiException(CommonErrorCode.NOT_FOUND);return r;}
 private TenantSupportModels.Policy policyView(TenantSupportModels.PolicyRow p,long t){return new TenantSupportModels.Policy(p!=null&&p.enabled(),p==null||p.roleId()==null?null:p.roleId().toString(),p==null||p.roleId()==null?null:roles.resolve(t,p.roleId()),p==null?FIELDS:readFields(p.allowedFieldsJson()),p==null?30:p.maxMinutes(),p==null?0:p.version(),has("iam:support:manage"),has("iam:support:review"));}
 private TenantSupportModels.Request view(SupportRequestModels.Row r,TenantSupportModels.PolicyRow p,LocalDateTime now,long t){
  var d=mapper.consent(t,r.id(),p==null?0:p.version());boolean pending="PLATFORM_APPROVED".equals(r.status())&&d==null,can=has("iam:support:review"),alive=r.requestedExpireAt().isAfter(now);var proposed=p!=null&&p.enabled()?proposed(r,p,t):null;LocalDateTime expires=p==null?null:now.plusMinutes(p.maxMinutes());if(expires!=null&&expires.isAfter(r.requestedExpireAt()))expires=r.requestedExpireAt();
  return new TenantSupportModels.Request(Long.toString(r.id()),r.bizNo(),r.operatorName(),r.ticketNo(),r.reason(),!alive&&Set.of("DRAFT","SUBMITTED","PLATFORM_APPROVED").contains(r.status())?"EXPIRED":r.status(),r.requestedExpireAt(),r.version(),p==null?0:p.version(),d==null?null:consentView(d),mapper.history(t,r.id()).stream().map(this::consentView).toList(),proposed,proposed==null?null:scopeHash(r,p,t,proposed),expires,can&&pending&&alive&&p!=null&&p.enabled()&&mapper.eligibleOperator(r.platformOperatorId(),now)!=null&&proposed!=null,can&&pending,can&&d!=null&&"APPROVED".equals(d.status()));
 }
 private String scopeHash(SupportRequestModels.Row r,TenantSupportModels.PolicyRow p,long t,TenantSupportModels.Scope scope){var role=roles.resolve(t,p.roleId());if(role==null)return null;String v=scope.tenantAll()+":"+String.join(",",new TreeSet<>(scope.organizations()))+":"+String.join(",",new TreeSet<>(scope.fields()))+":"+role.id()+":"+role.version()+":"+p.version()+":"+r.version();try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(v.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private TenantSupportModels.Consent consentView(TenantSupportModels.ConsentRow d){return new TenantSupportModels.Consent(Long.toString(d.id()),d.policyVersion(),d.requestVersion(),d.status(),d.roleId()==null?null:d.roleId().toString(),d.scopeJson()==null?null:readScope(d.scopeJson()),d.expiresAt(),Long.toString(d.reviewerUserId()),d.reviewerName(),d.comment(),d.decidedAt(),d.version(),d.revokedBy()==null?null:d.revokedBy().toString(),d.revokeReason(),d.revokedAt());}
 private SupportRequestModels.Tenant knownTenant(long t){var row=requests.lockTenant(t);if(row==null)throw new ApiException(CommonErrorCode.NOT_FOUND);return row;}
 private long tenant(String permission){var i=TenantContext.require();if(i.tenantId()<=0)throw new ApiException(CommonErrorCode.FORBIDDEN);require(permission);return i.tenantId();}
 private long actor(){return TenantContext.require().actorId();}private boolean has(String p){return AuthorizationContext.require().hasAction(p);}private void require(String p){if(!has(p))throw new ApiException(CommonErrorCode.FORBIDDEN);}
 private ApiException blocked(String m){return new ApiException(CommonErrorCode.RULE_BLOCKED,m);}private ApiException conflict(){return new ApiException(CommonErrorCode.CONFLICT,"支持策略、申请或审批已变化，请重新读取");}
 private long positive(String v){try{long n=Long.parseLong(v);if(n<=0)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new ApiException(CommonErrorCode.VALIDATION_FAILED);}}
 private void audit(String a,long id,Object after){audit.append(new AuditService.AuditCommand(a,"TENANT_SUPPORT",id,null,Map.of(),after,null,null));}
 private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}
 private Set<String> readFields(String v){try{return json.readValue(v,new TypeReference<Set<String>>(){});}catch(Exception e){throw new IllegalStateException(e);}}
 private TenantSupportModels.Scope readScope(String v){try{return json.readValue(v,TenantSupportModels.Scope.class);}catch(Exception e){throw new IllegalStateException(e);}}
}
